using Essco.Application.Liquidations;using Essco.Domain.Liquidations;namespace Essco.Tests.Unit.Liquidations;
public sealed class LiquidationTests
{[Fact]public void Rejects_inverted_main_range(){var x=Valid() with{From=new(2026,2,2),To=new(2026,2,1)};Assert.Contains(x.Validate(),e=>e.Contains("principal"));}[Fact]public async Task Service_normalizes_type(){var repo=new Repo();var result=await new LiquidationService(repo).SaveAsync(Valid() with{Type=" agentes "},true,default);Assert.True(result.Succeeded);Assert.Equal("AGENTES",repo.Value!.Type);}private static Liquidation Valid()=>new(){Kind=LiquidationKind.Agents,Date=new(2026,1,1),EmployeeCode="1",Identification="2",EmployeeName="A",From=new(2026,1,1),To=new(2026,1,2),ReceiptFrom=new(2026,1,1),ReceiptTo=new(2026,1,2),Notes="",Type="AGENTES",Route="",AgentCodes="",InvoiceReportCodes=""};private sealed class Repo:ILiquidationRepository{public Liquidation? Value{get;private set;}public ValueTask<LiquidationWriteResult>CreateAsync(Liquidation x,CancellationToken t){Value=x;return ValueTask.FromResult(new LiquidationWriteResult(true,1));}public ValueTask<LiquidationWriteResult>UpdateAsync(Liquidation x,CancellationToken t)=>throw new NotImplementedException();public ValueTask<bool>AnnulAsync(LiquidationKind k,int i,string y,CancellationToken t)=>throw new NotImplementedException();public ValueTask<IReadOnlyCollection<Liquidation>>ListAsync(LiquidationFilter f,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<Liquidation>>([]);}}
